'use strict';
const shades=[{"id":"brown","label":"بني","en":"BROWN","hex":"#804324"},{"id":"golden-yellow","label":"أصفر ذهبي","en":"GOLDEN YELLOW","hex":"#dda518"},{"id":"gray","label":"رمادي","en":"GRAY","hex":"#858990"},{"id":"green","label":"أخضر","en":"GREEN","hex":"#14732d"},{"id":"purple","label":"موف","en":"PURPLE","hex":"#8420a3"},{"id":"blue","label":"أزرق","en":"BLUE","hex":"#175bd2"},{"id":"blue-black","label":"أسود مزرق","en":"BLUE BLACK","hex":"#123452"},{"id":"black","label":"أسود","en":"BLACK","hex":"#242429"},{"id":"burgundy","label":"أحمر نبيتي","en":"BURGUNDY","hex":"#8a153a"},{"id":"fiery-red","label":"أحمر ناري","en":"FIERY RED","hex":"#da241d"}];
const products=[{id:'leave-in',name:'كريم Leave In',en:'LEAVE-IN CREAM',category:'care',categoryName:'العناية بالشعر',tag:'عناية',description:'مع زبدة الشيا، وفقًا للعبوة الظاهرة في صورة المجموعة.',short:'مع زبدة الشيا',keywords:'كريم ليف ان شيا عنايه شعر'},{id:'hair-powder',name:'بودرة الشعر',en:'HAIR POWDER',category:'style',categoryName:'تصفيف الشعر',tag:'تصفيف',description:'بودرة شعر كارين الظاهرة في صورة المجموعة. تفاصيل الاستخدام والمواصفات تُضاف بعد اعتمادها.',short:'Hair Powder · تصفيف الشعر',keywords:'بودره بودرة تصفيف شعر'}].concat(shades.map(s=>({id:"shade-"+s.id,name:"لون الشعر — "+s.label,en:s.en,category:"color",categoryName:"ألوان الشعر",tag:s.label,shade:s.label,image:"assets/colors/"+s.id+".jpg",description:"درجة "+s.label+" كما تظهر في الصورة الإعلانية المرسلة. صور الشعر توضيحية للحملة وليست ضمانًا لنتيجة الاستخدام.",short:"درجة "+s.label+" · صورة الحملة",keywords:"لون الوان صبغه صبغة كريزي كولور شعر "+s.label+" "+s.en})));
const heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.7c-2.4-2.4-6-1.4-8.8 1.5C9.2 3.3 5.6 2.3 3.2 4.7-.2 8.1 2 13 12 21c10-8 12.2-12.9 8.8-16.3Z"/></svg>';
const $=s=>document.querySelector(s);let favorites=[];try{const v=JSON.parse(localStorage.getItem('karin-atelier-favorites')||'[]');if(Array.isArray(v))favorites=[...new Set(v.filter(id=>products.some(p=>p.id===id)))];}catch{}let currentFilter='all',toastTimer;
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه');
function visual(p){if(p.image)return `<div class="product-media campaign-media"><img class="campaign-image" src="${p.image}" alt="صورة إعلان كارين بدرجة ${p.shade}" loading="lazy" width="1254" height="1254"></div>`;return `<div class="product-media ${p.category}"><div class="product-shadow"></div><img class="product-art ${p.category}" src="assets/collection.jpeg" alt="${p.name} من صورة مجموعة كارين" loading="lazy" width="447" height="447"></div>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
function syncFavorites(){const shadeSave=$('#shadeSave');if(shadeSave&&shadeSave.dataset.favorite)shadeSave.textContent=favorites.includes(shadeSave.dataset.favorite)?'إزالة من اختياراتي':'احفظي الدرجة ♡';try{localStorage.setItem('karin-atelier-favorites',JSON.stringify(favorites));}catch{}document.querySelectorAll('.saved-count').forEach(e=>e.textContent=favorites.length);document.querySelectorAll('[data-favorite]').forEach(b=>{const p=products.find(p=>p.id===b.dataset.favorite);const active=favorites.includes(b.dataset.favorite);b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',(active?'إزالة ':'حفظ ')+p.name+' '+(active?'من اختياراتي':'في اختياراتي'));});const detailSave=$('#detailSave');if(detailSave){const active=favorites.includes(detailSave.dataset.id);detailSave.textContent=active?'إزالة من اختياراتي':'احفظي في اختياراتي ♡';detailSave.setAttribute('aria-pressed',String(active));}}
function toggleFavorite(id){if(!products.some(p=>p.id===id))return;const exists=favorites.includes(id);favorites=exists?favorites.filter(x=>x!==id):[...favorites,id];syncFavorites();toast(exists?'اتشال من اختياراتك':'اتحفظ في اختياراتك ♡');if($('#savedDialog').open)renderSaved();}
function render(){const term=normalize($('#search').value.trim());let list=products.filter(p=>(currentFilter==='all'||p.category===currentFilter)&&normalize(p.name+' '+p.en+' '+p.keywords).includes(term));if($('#sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ar'));$('#products').innerHTML=list.map(p=>`<article class="product"><div class="product-media ${p.image?"campaign-media":p.category}">${p.image?`<img class="campaign-image" src="${p.image}" alt="صورة إعلان كارين بدرجة ${p.shade}" loading="lazy" width="1254" height="1254">`:`<div class="product-shadow"></div><img class="product-art ${p.category}" src="assets/collection.jpeg" alt="${p.name} من صورة مجموعة كارين" loading="lazy" width="447" height="447"><span class="product-tag">${p.tag}</span>`}<button class="icon-button favorite" data-favorite="${p.id}" aria-pressed="false" aria-label="حفظ ${p.name} في اختياراتي">${heart}</button></div><div class="product-copy"><span class="eyebrow">${p.en}</span><h3>${p.name}</h3><p>${p.short}</p><div class="product-price"><span>السعر قيد الاعتماد</span><span>معاينة المنتج</span></div><button class="detail-button" data-detail="${p.id}"><span>اكتشفي المنتج</span><span aria-hidden="true">↗</span></button></div></article>`).join('');$('#empty').hidden=list.length>0;$('#resultCount').textContent=list.length?'عرض '+list.length+' من '+products.length+' منتجات':'لا توجد نتائج';syncFavorites();}
function setFilter(value){currentFilter=value;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===value);b.setAttribute('aria-pressed',String(b.dataset.filter===value));});render();}
function showProduct(id){const p=products.find(x=>x.id===id);if(!p)return;$('#productDetail').innerHTML=`<div class="detail-layout"><div class="detail-visual">${visual(p)}</div><div class="detail-info"><span class="eyebrow">${p.en}</span><h2 id="dialogTitle">${p.name}</h2><p>${p.description}</p><dl class="specs"><div><dt>القسم</dt><dd>${p.categoryName}</dd></div><div><dt>السعر والتوافر</dt><dd>قيد الاعتماد</dd></div><div><dt>${p.shade?"الدرجة في الصورة":"الحجم والدرجات"}</dt><dd>${p.shade||"لم تُعتمد بعد"}</dd></div></dl><button class="button dark" id="detailSave" data-id="${p.id}" aria-pressed="false">احفظي في اختياراتي ♡</button><p class="detail-notice">الصورة من المواد المرسلة للعلامة. يتم استكمال تفاصيل الاستخدام والمواصفات قبل تفعيل البيع. لا يمكن إتمام شراء من هذه المعاينة.</p></div></div>`;syncFavorites();$('#productDialog').showModal();}
function renderSaved(){const list=favorites.map(id=>products.find(p=>p.id===id));$('#savedItems').innerHTML=list.length?list.map(p=>`<div class="saved-item"><div><h3>${p.name}</h3><p>${p.categoryName} · السعر قيد الاعتماد</p></div><button data-saved-detail="${p.id}">التفاصيل</button><button class="remove" data-remove="${p.id}" aria-label="إزالة ${p.name} من اختياراتي">×</button></div>`).join(''):'<div class="empty"><h3>لسه بتكتشفي لمستك؟</h3><p>احفظي المنتجات بعلامة القلب، وهتلاقيها هنا.</p></div>';}
document.addEventListener('click',e=>{const favorite=e.target.closest('[data-favorite]');if(favorite)toggleFavorite(favorite.dataset.favorite);const detail=e.target.closest('[data-detail]');if(detail)showProduct(detail.dataset.detail);const savedDetail=e.target.closest('[data-saved-detail]');if(savedDetail){$('#savedDialog').close();showProduct(savedDetail.dataset.savedDetail);}const remove=e.target.closest('[data-remove]');if(remove)toggleFavorite(remove.dataset.remove);if(e.target.closest('#detailSave'))toggleFavorite($('#detailSave').dataset.id);});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));document.querySelectorAll('[data-category-link]').forEach(a=>a.addEventListener('click',()=>{$('#search').value='';setFilter(a.dataset.categoryLink);}));document.querySelectorAll('[data-open-saved]').forEach(b=>b.addEventListener('click',()=>{renderSaved();$('#savedDialog').showModal();}));$('#continueBrowsing').onclick=()=>{$('#savedDialog').close();$('#shop').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};document.querySelectorAll('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
function setSearch(open){$('#searchPanel').hidden=!open;$('#searchToggle').setAttribute('aria-expanded',String(open));$('#searchToggle').setAttribute('aria-label',open?'إغلاق البحث':'فتح البحث');if(open){$('#search').focus();}else{$('#searchToggle').focus();}}$('#searchToggle').onclick=()=>setSearch($('#searchPanel').hidden);$('#searchClose').onclick=()=>setSearch(false);$('#search').addEventListener('input',()=>setFilter('all'));$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){setSearch(false);$('#shop').scrollIntoView();}if(e.key==='Escape'){setSearch(false);}});$('#sort').onchange=render;$('#reset').onclick=()=>{$('#search').value='';$('#sort').value='default';setFilter('all');};$('#year').textContent=new Date().getFullYear();render();


let selectedShade='burgundy';
function chooseShade(id){const s=shades.find(x=>x.id===id);if(!s)return;selectedShade=id;document.querySelectorAll('[data-shade]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.shade===id)));const image=$('#shadeImage');image.src='assets/colors/'+id+'.jpg';image.alt='الصورة الإعلانية لدرجة '+s.label+' من كارين';$('#shadeName').textContent=s.label;$('#shadeEnglish').textContent=s.en;$('#shadePosition').textContent=String(shades.indexOf(s)+1).padStart(2,'0')+' / 10';$('#shadeDetail').dataset.detail='shade-'+id;$('#shadeSave').dataset.favorite='shade-'+id;$('#shadeSave').textContent=favorites.includes('shade-'+id)?'إزالة من اختياراتي':'احفظي الدرجة ♡';syncFavorites();}
$('#shadeSwatches').innerHTML=shades.map(s=>'<button type="button" class="shade-swatch" data-shade="'+s.id+'" aria-label="اختيار درجة '+s.label+'" aria-pressed="false"><span style="--swatch:'+s.hex+'"></span><small>'+s.label+'</small></button>').join('');document.querySelectorAll('[data-shade]').forEach(b=>b.onclick=()=>chooseShade(b.dataset.shade));$('#shadeNext').onclick=()=>chooseShade(shades[(shades.findIndex(s=>s.id===selectedShade)+1)%shades.length].id);$('#shadePrevious').onclick=()=>chooseShade(shades[(shades.findIndex(s=>s.id===selectedShade)+shades.length-1)%shades.length].id);chooseShade(selectedShade);
